unsafe fn build_tree(mut s: *mut deflate_state, mut desc: *mut tree_desc) {
    let tree: *mut ct_data = (*desc).dyn_tree;
    let stree: *const ct_data = (*(*desc).stat_desc).static_tree;
    let elems: c_int = (*(*desc).stat_desc).elems;

    let s_ref: &mut deflate_state = unsafe { &mut *s }; // SAFETY: caller guarantees `s` is a valid, unique pointer for the duration of this function.
    let desc_ref: &mut tree_desc = unsafe { &mut *desc }; // SAFETY: caller guarantees `desc` is a valid, unique pointer for the duration of this function.

    let mut max_code: c_int = -1;
    let mut node: c_int;

    s_ref.heap_len = 0;
    s_ref.heap_max = HEAP_SIZE;

    let mut n: c_int = 0;
    while n < elems {
        let t = unsafe { tree.add(n as usize) }; // SAFETY: `n < elems`, and caller provides a valid tree with at least `elems` entries.
        if unsafe { (*t).fc.freq as c_int } != 0 {
            max_code = n;
            s_ref.heap_len += 1;
            s_ref.heap[s_ref.heap_len as usize] = n;
            s_ref.depth[n as usize] = 0 as uch;
        } else {
            unsafe { (*t).dl.len = 0 as ush }; // SAFETY: same bounds as above; writing current node's length is valid.
        }
        n += 1;
    }

    while s_ref.heap_len < 2 {
        s_ref.heap_len += 1;
        let inserted = if max_code < 2 {
            max_code += 1;
            max_code
        } else {
            0
        };
        s_ref.heap[s_ref.heap_len as usize] = inserted;
        let t = unsafe { tree.add(inserted as usize) }; // SAFETY: inserted is either 0, 1, or 2 here, all valid tree indices for zlib trees.
        unsafe { (*t).fc.freq = 1 as ush }; // SAFETY: same as above.
        s_ref.depth[inserted as usize] = 0 as uch;
        s_ref.opt_len = s_ref.opt_len.wrapping_sub(1);
        if !stree.is_null() {
            s_ref.static_len = (s_ref.static_len as c_ulong)
                .wrapping_sub(unsafe { (*stree.add(inserted as usize)).dl.len as c_ulong })
                as ulg;
        }
    }

    desc_ref.max_code = max_code;

    n = s_ref.heap_len / 2;
    while n >= 1 {
        unsafe { pqdownheap(s, tree, n) }; // SAFETY: heap/tree/state invariants are established above and match original function's requirements.
        n -= 1;
    }

    node = elems;
    loop {
        n = s_ref.heap[SMALLEST as usize];
        let last = s_ref.heap[s_ref.heap_len as usize];
        s_ref.heap_len -= 1;
        s_ref.heap[SMALLEST as usize] = last;
        unsafe { pqdownheap(s, tree, SMALLEST) }; // SAFETY: heap/tree/state invariants are maintained exactly as in the original code.

        let m: c_int = s_ref.heap[SMALLEST as usize];

        s_ref.heap_max -= 1;
        s_ref.heap[s_ref.heap_max as usize] = n;
        s_ref.heap_max -= 1;
        s_ref.heap[s_ref.heap_max as usize] = m;

        let tn = unsafe { tree.add(n as usize) }; // SAFETY: `n` comes from heap entries previously populated with valid tree indices.
        let tm = unsafe { tree.add(m as usize) }; // SAFETY: `m` comes from heap entries previously populated with valid tree indices.
        let tnode = unsafe { tree.add(node as usize) }; // SAFETY: `node` starts at `elems` and advances within the allocated tree workspace as in original zlib logic.

        unsafe {
            (*tnode).fc.freq = ((*tn).fc.freq as c_int + (*tm).fc.freq as c_int) as ush;
        } // SAFETY: all three pointers are valid tree nodes as established above.

        let dn = s_ref.depth[n as usize] as c_int;
        let dm = s_ref.depth[m as usize] as c_int;
        s_ref.depth[node as usize] = (if dn >= dm { dn } else { dm } + 1) as uch;

        unsafe {
            (*tm).dl.dad = node as ush;
            (*tn).dl.dad = (*tm).dl.dad;
        } // SAFETY: `tn` and `tm` are valid mutable tree nodes.

        let new_node = node;
        node += 1;
        s_ref.heap[SMALLEST as usize] = new_node;
        unsafe { pqdownheap(s, tree, SMALLEST) }; // SAFETY: heap/tree/state invariants are maintained exactly as in the original code.

        if s_ref.heap_len < 2 {
            break;
        }
    }

    s_ref.heap_max -= 1;
    s_ref.heap[s_ref.heap_max as usize] = s_ref.heap[SMALLEST as usize];
    unsafe { gen_bitlen(s, desc) }; // SAFETY: tree construction is complete and matches original preconditions.
    unsafe { gen_codes(tree, max_code, &raw mut s_ref.bl_count as *mut ushf) }; // SAFETY: `tree` and `bl_count` are valid and initialized as required by original code.
